#!/usr/bin/env bash
set -Eeuo pipefail

# Serial runner for the qwen35 PDU eps sweep: executes every pdu_eps*.yaml
# (generated by make_eps_configs.py from the measured anchor) one after
# another via this directory's copy of main_run_train.sh. A failed arm is
# logged and the sequence continues (main_run_train.sh semantics).
SCRIPT_DIR=$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)

shopt -s nullglob
CONFIGS=("${SCRIPT_DIR}"/pdu_eps*.yaml)
shopt -u nullglob

if (( ${#CONFIGS[@]} == 0 )); then
  echo "ERROR: no pdu_eps*.yaml in ${SCRIPT_DIR}." >&2
  echo "Run: python3 ${SCRIPT_DIR}/make_eps_configs.py  (after the anchor job finishes)" >&2
  exit 1
fi

echo "PDU eps sweep: ${#CONFIGS[@]} arm(s): ${CONFIGS[*]}"
exec bash "${SCRIPT_DIR}/main_run_train.sh" "${CONFIGS[@]}"
